// Normalize whatever entry fed us into one item per email:
//   { message_id, from_email, from_name, subject, body, email_date, arrived_ms }
// Entries: Webhook (body = one email, an array, or {emails:[...]}),
//          the sample fetch (repo JSON), or a Gmail Trigger item (simplified shape).
// Hard cap: MAX_EMAILS per run so one bad POST cannot burn the Anthropic budget.
const MAX_EMAILS = 25;

let raw = [];
for (const it of $input.all()) {
  let b = it.json;
  if (b && b.body && typeof b.body === "object" && (b.headers || b.query))
    b = b.body; // Webhook wrapper
  if (Array.isArray(b)) raw.push(...b);
  else if (b && Array.isArray(b.emails)) raw.push(...b.emails);
  else if (b && Array.isArray(b.data)) raw.push(...b.data);
  else if (b) raw.push(b);
}

// djb2 string hash -> stable fallback id when a feed carries no Message-ID.
function hash(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return "gen-" + (h >>> 0).toString(16);
}
function addr(v) {
  if (!v) return { email: null, name: null };
  if (typeof v === "object") {
    if (Array.isArray(v.value) && v.value[0])
      return {
        email: v.value[0].address || null,
        name: v.value[0].name || null,
      };
    return { email: v.address || v.email || null, name: v.name || null };
  }
  const s = String(v);
  const m = s.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/);
  if (m) return { email: m[2].trim().toLowerCase(), name: m[1].trim() || null };
  return { email: s.trim().toLowerCase(), name: null };
}

const seen = new Set();
const out = [];
const now = Date.now();
for (const e of raw) {
  if (!e || typeof e !== "object") continue;
  const a = addr(e.from || e.From || e.from_email || e.sender);
  const subject = String(e.subject || e.Subject || "").trim();
  const body = String(
    e.body || e.text || e.textPlain || e.snippet || e.html || "",
  ).trim();
  if (!body && !subject) continue;
  let id =
    e.message_id ||
    e.messageId ||
    e.id ||
    (e.headers && e.headers["message-id"]) ||
    "";
  id = String(id).trim().replace(/^<|>$/g, "");
  if (!id) id = hash((a.email || "") + "|" + subject + "|" + body);
  if (seen.has(id)) continue; // same email twice in one feed = one row
  seen.add(id);
  out.push({
    json: {
      message_id: id,
      from_email: a.email || (e.from_name ? null : null),
      from_name: e.from_name || a.name || null,
      subject: subject || "(no subject)",
      body,
      email_date: e.received_at || e.date || e.internalDate || null,
      arrived_ms: now,
      emails_in_feed: raw.length,
    },
  });
}
if (!out.length)
  throw new Error(
    "No emails in the feed. POST {from, subject, body, message_id} or {emails:[...]}.",
  );
const dropped = out.length - Math.min(out.length, MAX_EMAILS);
const kept = out.slice(0, MAX_EMAILS);
for (const k of kept) k.json.emails_dropped_by_cap = dropped;
return kept;

// Validate every field Claude returned. Unknown -> null, never invented.
// Input: the raw /v1/messages response (tool_use forced). Paired email = the Config item.
const FIELDS = [
  "origin_port",
  "destination_port",
  "mode",
  "weight_kg",
  "dimensions",
  "cargo_type",
  "incoterm",
  "deadline",
];
const INCOTERMS = [
  "EXW",
  "FCA",
  "FAS",
  "FOB",
  "CFR",
  "CIF",
  "CPT",
  "CIP",
  "DAP",
  "DPU",
  "DDP",
];
const MODES = ["FCL", "LCL", "AIR", "ROAD", "RAIL"];

const email = $("Config").item.json;
const resp = $json || {};

let x = null;
let parse_error = null;
try {
  const content = Array.isArray(resp.content) ? resp.content : [];
  const tool = content.find(function (c) {
    return c && c.type === "tool_use" && c.input;
  });
  if (tool) x = tool.input;
  else {
    const txt = content
      .filter(function (c) {
        return c && c.type === "text";
      })
      .map(function (c) {
        return c.text;
      })
      .join("");
    const m = txt.match(/\{[\s\S]*\}/);
    if (m) x = JSON.parse(m[0]);
  }
} catch (e) {
  parse_error = String(e.message || e);
}
if (!x || typeof x !== "object") {
  x = {};
  parse_error = parse_error || "no tool_use block in the response";
}

function str(v, max) {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\s+/g, " ").trim();
  if (!s || /^(null|none|n\/a|unknown|not stated|not specified|-)$/i.test(s))
    return null;
  return s.slice(0, max || 200);
}
function num(v) {
  if (v === null || v === undefined || v === "") return null;
  const n =
    typeof v === "number" ? v : parseFloat(String(v).replace(/[^0-9.]/g, ""));
  return isFinite(n) && n > 0 ? Math.round(n * 100) / 100 : null;
}
function oneOf(v, list) {
  const s = str(v, 10);
  if (!s) return null;
  const u = s.toUpperCase();
  return list.indexOf(u) >= 0 ? u : null;
}

const out = {
  origin_port: str(x.origin_port, 120),
  destination_port: str(x.destination_port, 120),
  mode: oneOf(x.mode, MODES),
  weight_kg: num(x.weight_kg),
  dimensions: str(x.dimensions, 200),
  cargo_type: str(x.cargo_type, 120),
  incoterm: oneOf(x.incoterm, INCOTERMS),
  deadline: str(x.deadline, 80),
  pieces: (function (v) {
    const n = parseInt(v, 10);
    return isFinite(n) && n > 0 ? n : null;
  })(x.pieces),
  notes: str(x.notes, 300),
};
// deadline: ISO date when the model could resolve one, otherwise the sender's own words.
out.deadline_is_date = !!(
  out.deadline && /^\d{4}-\d{2}-\d{2}$/.test(out.deadline)
);

let fields_filled = 0;
for (const f of FIELDS) if (out[f] !== null) fields_filled++;

let confidence =
  typeof x.confidence === "number" ? x.confidence : parseFloat(x.confidence);
if (!isFinite(confidence)) confidence = fields_filled / FIELDS.length;
confidence = Math.max(0, Math.min(1, confidence));
if (parse_error || fields_filled === 0) confidence = 0;
confidence = Math.round(confidence * 100) / 100;

const usage = resp.usage || {};
return {
    json: Object.assign(
      {
        message_id: email.message_id,
        from_email: email.from_email,
        from_name: email.from_name,
        subject: email.subject,
        email_date: email.email_date,
        arrived_ms: email.arrived_ms,
        run_id: email.run_id,
        model: email.model,
        fields_filled,
        fields_total: FIELDS.length,
        confidence,
        parse_error,
        tokens_in: usage.input_tokens || 0,
        tokens_out: usage.output_tokens || 0,
        raw_extraction: x,
      },
      out,
    ),
  };

// Build the confirmation reply as a DRAFT. Echoes every extracted field, marks
// the ones we could not find, and asks the sender to confirm. Nothing here sends.
const NL = String.fromCharCode(10);
const q = $("Validate + score").item.json;
const email = $("Config").item.json;

function show(v, suffix) {
  if (v === null || v === undefined || v === "")
    return "NOT FOUND - please confirm";
  return String(v) + (suffix || "");
}
const first = (email.from_name || "").split(" ")[0];
const greeting = first ? "Hi " + first + "," : "Hello,";
const subj = /^re:/i.test(email.subject || "")
  ? email.subject
  : "Re: " + (email.subject || "your quote request");

let dims = q.dimensions;
if (
  dims &&
  q.pieces &&
  !/x\s*\d+\s*(pallet|piece|carton|crate|unit|box|bag|drum)/i.test(dims)
)
  dims = dims + " (" + q.pieces + " pieces)";

const lines = [
  greeting,
  "",
  "Thanks for your enquiry. Before we price it, please check that we read it right:",
  "",
  "- Origin: " + show(q.origin_port),
  "- Destination: " + show(q.destination_port),
  "- Mode: " + show(q.mode),
  "- Gross weight: " + show(q.weight_kg, " kg"),
  "- Dimensions: " + show(dims),
  "- Cargo: " + show(q.cargo_type),
  "- Incoterm: " + show(q.incoterm),
  "- Needed by: " +
    show(q.deadline) +
    (q.deadline && !q.deadline_is_date ? " (please give us a date)" : ""),
  "",
  "Anything marked NOT FOUND we could not see in your email. Reply with the missing details and we will send the quote the same day.",
  "",
  "Kind regards,",
  "Quotes desk",
  "",
  "[DRAFT - created by the quote parser, review before sending. Fields filled: " +
    q.fields_filled +
    "/" +
    q.fields_total +
    ", confidence " +
    q.confidence +
    "]",
];

return {
    json: {
      message_id: q.message_id,
      to_email: q.from_email,
      subject: subj,
      body: lines.join(NL),
      fields_filled: q.fields_filled,
      confidence: q.confidence,
      run_id: q.run_id,
    },
  };

// One summary item, read straight off the execution panel.
// fields_filled_avg = of 8 schema fields; seconds_avg = email entering the workflow -> row written (from the UPSERT RETURNING).
const emails = $("Normalize email").all();
const rows = $("UPSERT ep04_quotes")
  .all()
  .map(function (i) {
    return i.json;
  });
const drafts = $input.all();
const claude = $("Claude extract")
  .all()
  .map(function (i) {
    return i.json;
  });

function avg(list, key, digits) {
  const v = list
    .map(function (r) {
      return Number(r[key]);
    })
    .filter(function (n) {
      return isFinite(n);
    });
  if (!v.length) return null;
  const m =
    v.reduce(function (a, b) {
      return a + b;
    }, 0) / v.length;
  const p = Math.pow(10, digits || 1);
  return Math.round(m * p) / p;
}
const first = emails[0] ? emails[0].json : {};
const cfg = $("Config").first().json;
const tokens_in = claude.reduce(function (a, r) {
  return a + ((r.usage && r.usage.input_tokens) || 0);
}, 0);
const tokens_out = claude.reduce(function (a, r) {
  return a + ((r.usage && r.usage.output_tokens) || 0);
}, 0);

return [
  {
    json: {
      run_id: cfg.run_id,
      model: cfg.model,
      emails_seen: emails.length,
      emails_dropped_by_cap: first.emails_dropped_by_cap || 0,
      rows_written: rows.length,
      rows_inserted: rows.filter(function (r) {
        return r.inserted === true;
      }).length,
      rows_updated: rows.filter(function (r) {
        return r.inserted === false;
      }).length,
      drafts_written: drafts.length,
      fields_filled_avg: avg(rows, "fields_filled", 2),
      fields_total: 8,
      confidence_avg: avg(rows, "confidence", 2),
      seconds_avg: avg(rows, "seconds_to_row", 1),
      seconds_total:
        Math.round((Date.now() - (first.arrived_ms || Date.now())) / 100) / 10,
      tokens_in,
      tokens_out,
    },
  },
];
